(function(){
const id='balance-main';const stages=[{"title": "读懂天平", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>2</mn><mi>x</mi><mo>+</mo><mn>3</mn><mo>=</mo><mn>11</mn></mrow></math>", "plain": "2x+3=11", "reason": "左盘是两个相同袋子和三个单位块，右盘是十一个单位块。天平平放，表示两盘总量相同。每袋数量用 x 表示；2x 表示 2 × x，即两份相同的 x。", "next": "两边同时拿走 3 块"}, {"title": "两边拿走相同数量", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mo>(</mo><mn>2</mn><mi>x</mi><mo>+</mo><mn>3</mn><mo>)</mo><mo>−</mo><mn>3</mn><mo>=</mo><mn>11</mn><mo>−</mo><mn>3</mn></mrow></math>", "plain": "(2x+3)−3=11−3", "reason": "承接两盘相等；现在两边同时减去 3。原来一样多，同时拿走一样多，剩下的仍一样多。淡色方块标记已经拿走的三个单位。", "next": "整理左边"}, {"title": "左边只剩两袋", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>2</mn><mi>x</mi><mo>=</mo><mn>11</mn><mo>−</mo><mn>3</mn></mrow></math>", "plain": "2x=11−3", "reason": "承接两边减去 3 的结果；左边原有的三个单位已全部拿走，所以只剩两份 x。右边的计算先保留。", "next": "数清右边"}, {"title": "右边剩八块", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>2</mn><mi>x</mi><mo>=</mo><mn>8</mn></mrow></math>", "plain": "2x=8", "reason": "承接左边只剩 2x；右边原有 11 块，拿走 3 块后剩 8 块。两袋合起来对应八个单位。", "next": "两边平均分成 2 份"}, {"title": "两边同样分组", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mo>(</mo><mn>2</mn><mi>x</mi><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>8</mn><mo>÷</mo><mn>2</mn></mrow></math>", "plain": "(2x)÷2=8÷2", "reason": "承接两袋与八块一样多；两边都平均分成 2 份，每份仍一样多。2 不是零，因此可以作为 divisor（除数）。虚线框表示两边各有两组。", "next": "看左边每一份"}, {"title": "左边每份是一袋", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>x</mi><mo>=</mo><mn>8</mn><mo>÷</mo><mn>2</mn></mrow></math>", "plain": "x=8÷2", "reason": "承接两边都平均分成两份；左边两袋分成两组，每组恰好一袋，所以左边每份是 x。右边每份仍写为 8 ÷ 2。", "next": "数出右边每一份"}, {"title": "一袋对应四块", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mi>x</mi><mo>=</mo><mn>4</mn></mrow></math>", "plain": "x=4", "reason": "承接每袋对应八块的一半；八块平均分成两组，每组四块。所以 solution（解）是 4：让原来的 equation 成立的 x 数值。", "next": "检查原来的条件"}, {"title": "把 4 放回原式", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>2</mn><mo>×</mo><mn>4</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>11</mn></mrow></math>", "plain": "2×4+3=11", "reason": "承接每袋四个单位；用 4 替换原式的 x。必须回到原式检查，不能只看最后一行。", "next": "先算两袋"}, {"title": "先计算乘法", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>8</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>11</mn></mrow></math>", "plain": "8+3=11", "reason": "承接原式中的 2 × 4 + 3；先算两袋共八个单位，三个额外单位仍保留。", "next": "再加三个单位"}, {"title": "检查通过", "formula": "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><mrow><mn>11</mn><mo>=</mo><mn>11</mn></mrow></math>", "plain": "11=11", "reason": "承接 8 + 3；再加三个单位得到 11，与右盘的 11 相同。模型两边都显示十一块，原来的条件成立。", "next": ""}];
let root,state={step:0,one:false};
const q=s=>root.querySelector(s);
function box(x,y,label,kind='unit',opacity=1){return `<g opacity="${opacity}"><rect x="${x}" y="${y}" width="${kind==='bag'?56:25}" height="${kind==='bag'?49:25}" rx="5" fill="${kind==='bag'?'#d3e7ff':'#c8cbd2'}" stroke="${kind==='bag'?'#0066cc':'#6f7580'}"/><text x="${x+(kind==='bag'?28:12.5)}" y="${y+(kind==='bag'?32:19)}" text-anchor="middle">${label}</text></g>`;}
function units(n,x,y,ghost=0){let out='';for(let i=0;i<n;i++)out+=box(x+(i%4)*31,y-Math.floor(i/4)*31,'1');for(let i=0;i<ghost;i++)out+=box(x+155+i*29,y,'1','unit',.22);return out;}
function draw(){
 const i=state.step,unbalanced=state.one,removed=i>0||unbalanced,grouped=i>=4&&i<=5,isolated=i===6,check=i>=7;
 let left,right;
 if(check){left=units(8,50,173)+units(3,205,173);right=units(11,432,173);}
 else if(isolated){left=box(142,149,'x','bag');right=units(4,423,173);}
 else {left=box(70,149,'x','bag')+box(168,149,'x','bag')+(removed?units(0,45,112,3):units(3,66,112));right=units(removed&&!unbalanced?8:11,422,173,removed&&!unbalanced&&i<4?3:0);}
 if(grouped){left+='<rect x="60" y="135" width="78" height="70" rx="8" fill="none" stroke="#0066cc" stroke-dasharray="5 4"/><rect x="158" y="135" width="78" height="70" rx="8" fill="none" stroke="#0066cc" stroke-dasharray="5 4"/>';right+='<rect x="410" y="137" width="140" height="30" rx="7" fill="none" stroke="#0066cc" stroke-dasharray="5 4"/><rect x="410" y="171" width="140" height="30" rx="7" fill="none" stroke="#0066cc" stroke-dasharray="5 4"/>';}
 const ly=unbalanced?-20:0,ry=unbalanced?20:0;
 q('[data-drawing]').innerHTML=`<path d="M300 260 L330 206 L360 260 Z" fill="#7b8493"/><line x1="95" y1="${209+ly}" x2="565" y2="${209+ry}" stroke="#596577" stroke-width="6"/><g transform="translate(0 ${ly})">${left}<line x1="35" y1="206" x2="280" y2="206" stroke="#596577" stroke-width="5"/></g><g transform="translate(0 ${ry})">${right}<line x1="382" y1="206" x2="625" y2="206" stroke="#596577" stroke-width="5"/></g><text x="155" y="32" text-anchor="middle">${check?'两袋与额外单位':isolated?'一袋':'左盘'}</text><text x="490" y="32" text-anchor="middle">${isolated?'四个单位':'右盘'}</text><text x="330" y="88" text-anchor="middle" font-weight="700">${unbalanced?'≠ 不再一样多':'＝ 一样多'}</text>`;
 q('svg').setAttribute('aria-label',unbalanced?'左盘单独拿走三块后变轻，右盘下沉，左右不再相等':`第${i+1}步，左右仍相等。${stages[i].plain}`);
 q('[data-stage-title]').textContent=unbalanced?'只改一边会发生什么？':`${i+1} / ${stages.length} · ${stages[i].title}`;
 q('[data-formula]').innerHTML=unbalanced?'<math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mn>2</mn><mi>x</mi><mo>≠</mo><mn>11</mn></mrow></math>':stages[i].formula;
 q('[data-reason]').textContent=unbalanced?'左盘拿走三个单位，右盘仍有十一个。左边变轻，右盘下沉，所以不能把这一步写成仍然相等。点击「恢复原来两盘」，再试两边同时拿走。':stages[i].reason;
 q('[data-next]').textContent=unbalanced?'恢复原来两盘':stages[i].next||'已经检查完成';q('[data-next]').disabled=!unbalanced&&i===stages.length-1;
 q('[data-one]').hidden=i!==0||unbalanced;q('[data-prev]').disabled=i===0&&!unbalanced;
}
function save(){document.dispatchEvent(new CustomEvent('dt:exploration',{detail:{activityId:id,state}}));}
function recover(s){state={step:Number.isInteger(s.step)?Math.max(0,Math.min(stages.length-1,s.step)):0,one:s.one===true};if(state.step!==0)state.one=false;draw();}
document.addEventListener('dt:activity-mounted',e=>{if(e.detail.activityId!==id)return;root=document.querySelector('[data-dt-activity="'+id+'"]');q('[data-full]').innerHTML=stages.map(s=>`<div><h4>${s.title}</h4>${s.formula}<p>${s.reason}</p></div>`).join('');q('[data-next]').onclick=()=>{if(state.one)state={step:0,one:false};else state.step=Math.min(stages.length-1,state.step+1);draw();save();};q('[data-prev]').onclick=()=>{state.one=false;state.step=Math.max(0,state.step-1);draw();save();};q('[data-one]').onclick=()=>{state.one=true;draw();save();};q('[data-reset]').onclick=()=>{state={step:0,one:false};draw();save();};recover(e.detail.state||{});});
document.addEventListener('dt:restore',e=>{if(e.detail.activityId===id&&root)recover(e.detail.state||{});});
})();
